private void startAllWhirlpool(){
  try {
    for (Map.Entry<String, Whirlpool> entry : whirlpoolMap.entrySet().stream()
        .filter(entry -> entry.getValue().hasWallet() && !entry.getValue().isStarted())
        .collect(Collectors.toList())) {
      Wallet wallet = AppServices.get().getWallet(entry.getKey());
      Whirlpool whirlpool = entry.getValue();
      startWhirlpool(wallet, whirlpool, false);
    }
  } catch (IllegalStateException e) {
    // 捕获并处理可能的IllegalStateException
    System.err.println("运行时异常被捕获: " + e.getMessage());
    e.printStackTrace();
  }
}
